package com.nettakrim.signed_paintings.rendering;

import com.nettakrim.signed_paintings.SignedPaintingsClient;
import com.nettakrim.signed_paintings.util.ImageManager;

public class OverlayInfo extends ImageInfo {
    public OverlayInfo() {

    }

    public void loadOverlay(String text) {
        invalidateImage();
        String url = SignedPaintingsClient.imageManager.applyURLInferences(text);
        // with text like "Hello" it will infer "https://Hello" which wont be a valid url
        // calling getDomain on a url like this will result in "https://", so this is easy to test for
        // text like "Hello/Hi" will infer as "https://Hello/Hi", which looks enough like a url that it cant really be fixed
        // however checking if the url is valid eliminates something like "https://Hello / Hi"
        if (!SignedPaintingsClient.getDomain(url).equals("https://") && ImageManager.isValid(url)) {
            SignedPaintingsClient.imageManager.loadImage(url, this::updateImage);
        }
    }
}

package com.nettakrim.signed_paintings.rendering;

public class BackType {
    public enum Type {
        SIGN,
        BLOCK,
        NONE
    }

    public static Type cycle(Type type) {
        return switch (type) {
            case SIGN -> Type.BLOCK;
            case BLOCK -> Type.NONE;
            case NONE -> Type.SIGN;
        };
    }

    public static String getName(Type type) {
        return switch (type) {
            case SIGN -> "S";
            case BLOCK -> "B";
            case NONE -> "N";
        };
    }

    public static Type parseBackType(String name) {
        if (name.equals("S")) return Type.SIGN;
        if (name.equals("B")) return Type.BLOCK;
        if (name.equals("N")) return Type.NONE;
        return Type.SIGN;
    }
}

package com.nettakrim.signed_paintings.rendering;

public class Centering {
    public enum Type {
        MIN(0),
        CENTER(1),
        MAX(2);

        private final int index;

        Type(int index) {
            this.index = index;
        }

        public int getIndex() {
            return index;
        }
    }

    public static float getOffset(float size, Type centering) {
        return switch (centering) {
            case MIN -> (size - 1) / 2;
            case CENTER -> 0;
            case MAX -> (1 - size) / 2;
        };
    }

    public static String getName(boolean xAxis, Type centering) {
        return switch (centering) {
            case MIN -> xAxis ? "R" : "T";
            case CENTER -> "C";
            case MAX -> xAxis ? "L" : "B";
        };
    }

    public static Type parseCentering(String name) {
        if (name.equals("C")) return Type.CENTER;
        if (name.equals("R") || name.equals("T")) return Type.MIN;
        if (name.equals("L") || name.equals("B")) return Type.MAX;
        return Type.CENTER;
    }
}

